// Extract message from OmniFlow/Evolution webhook payload
const body = $input.first().json;
const msg = body?.data?.message?.conversation
  || body?.data?.message?.extendedTextMessage?.text
  || body?.message?.conversation
  || body?.text
  || '';
const phone = body?.data?.key?.remoteJid
  || body?.from
  || body?.phone
  || '';
const from = phone.replace('@s.whatsapp.net', '').replace('@c.us', '');
return [{ json: { msg: msg.trim(), phone: from, rawMsg: msg } }];

const msg = $input.first().json.msg.toLowerCase();
const phone = $input.first().json.phone;

// Classify intent
let intent = 'greeting';
let query = '';

if (/precio|cuanto|cuesta|valor|cotiz|presupuesto|cuánto/i.test(msg)) {
  intent = 'price_query';
  query = msg.replace(/precio|cuanto|cuesta|valor|cotiz|presupuesto|cuánto/gi, '').trim();
} else if (/catalogo|catálogo|productos|tienen|venden|tipos/i.test(msg)) {
  intent = 'catalog';
} else if (/agendar|agenda|visita|instalar|instalacion|instalación|cuando/i.test(msg)) {
  intent = 'booking';
} else if (/hola|buenas|buen dia|buenos dias|saludos|hi|hello/i.test(msg)) {
  intent = 'greeting';
} else if (/gracias|ok|perfecto|excelente|listo/i.test(msg)) {
  intent = 'thanks';
}

return [{ json: { intent, query: query || msg, phone, original: $input.first().json.msg } }];

const intent = $('Classify Intent').first().json.intent;
const original = $('Classify Intent').first().json.original;
const phone = $('Classify Intent').first().json.phone;
let response = '';

if (intent === 'price_query') {
  try {
    const products = $('Search Products (price query)').first().json.products || [];
    if (products.length > 0) {
      response = `Hola 👋 Encontré estos productos relacionados:\n\n`;
      products.forEach(p => {
        response += `• *${p.name}*\n  ${p.price}\n  ${p.description || ''}\n\n`;
      });
      response += `Para una cotización exacta a medida, visita: https://terrablinds.cl/quote 📐`;
    } else {
      response = `Hola 👋 No encontré ese producto específico. Puedes ver todo nuestro catálogo en: https://terrablinds.cl/catalog\n\nO escríbeme qué tipo de cortina buscas y te ayudo.`;
    }
  } catch (e) {
    response = `Hola 👋 Para consultar precios exactos a medida, visita: https://terrablinds.cl/quote\n\nNuestro equipo también puede asesorarte personalmente 😊`;
  }
} else if (intent === 'catalog') {
  response = `Hola 👋 Trabajamos con:\n\n• Cortinas Roller (Blackout, Sunscreen, Duo)\n• Persianas de Madera y PVC\n• Toldos Retráctiles\n• Cierres de Terraza (PVC y Cristal)\n• Cortinas Motorizadas\n• Domótica y Control WiFi\n\nVer catálogo completo: https://terrablinds.cl/catalog`;
} else if (intent === 'booking') {
  response = `Hola 👋 Para agendar una visita técnica o toma de medidas, puedes hacerlo online aquí:\n\n📅 https://terrablinds.cl/agendar\n\nO si prefieres, dime tu nombre y disponibilidad y te contacto directamente.`;
} else if (intent === 'thanks') {
  response = `¡Gracias a ti! 😊 Si necesitas algo más, aquí estoy. Puedes cotizar en cualquier momento en: https://terrablinds.cl/quote`;
} else {
  response = `¡Hola! 👋 Soy el asistente de *TerraBlinds*.\n\nPuedo ayudarte con:\n• 💰 Precios de cortinas y persianas\n• 📋 Información sobre productos\n• 📅 Agendar visita técnica\n\n¿En qué te puedo ayudar hoy?`;
}

return [{ json: { phone, response, intent } }];
